using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options that can resolve ANY type (default reflection resolver) ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing.
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
}

// --- Options with a narrow source-gen context (only knows about Person) ---
var narrow = new JsonSerializerOptions { TypeInfoResolver = NarrowContext.Default };

// Person IS in the context → should succeed
if (narrow.TryGetTypeInfo<Person>(out var found))
    Console.WriteLine($"Narrow context has Person: {found!.Type.Name}");
else
    Console.WriteLine("Narrow context does NOT have Person");

// int[] is NOT in the context → should return false, no exception
if (narrow.TryGetTypeInfo<int[]>(out var missing))
    Console.WriteLine($"Narrow context has int[]: {missing!.Type.Name}");
else
    Console.WriteLine("Narrow context does NOT have int[] (expected)");

// --- Types ---
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class NarrowContext : JsonSerializerContext;

